import { GameContext } from '@/core/engine/game-context';
import { GameStateManager } from '@/core/systems/game-state-manager';
export class PlayerPositionTriggerCondition {
    playerAnimations;
    gameStateManager;
    constructor(playerAnimations) {
        this.playerAnimations = playerAnimations;
        const gameContext = GameContext.getInstance();
        this.gameStateManager = gameContext.getBean(GameStateManager);
    }
    isMet() {
        const spritePosition = this.gameStateManager.getState().player.spritePosition;
        return this.playerAnimations.some((playerAnimation) => playerAnimation === spritePosition);
    }
}
